{
  "$schema": "https://raw.githubusercontent.com/google-gemini/gemini-cli/main/schemas/settings.schema.json",
  "security": {
    "sandbox": "podman",
    "auth": {
      "selectedType": "oauth-personal"
    },
    "disableYoloMode": true
  },
  "general": {
    "previewFeatures": true,
    "preferredEditor": "emacs"
  },
  "ui": {
    "theme": "",
    "hideBanner": true,
    "showMemoryUsage": true,
    "showLineNumbers": true,
    "showCitations": true,
    "showModelInfoInChat": true,
    "useFullWidth": true,
    "hideContextSummary": true,
    "footer": {
      "hideSandboxStatus": true
    }
  },
  "context": {
    "discoveryMaxDirs": 200,
    "fileFiltering": {
      "respectGitIgnore": false,
      "respectGeminiIgnore": true
    }
  },
  "tools": {
    "sandbox": "podman",
    "shell": {
      "enableInteractiveShell": true,
      "pager": "cat",
      "showColor": true
    },
    "useRipgrep": true,
    "enableToolOutputTruncation": true,
    "truncateToolOutputThreshold": 4000000,
    "truncateToolOutputLines": 1000
  },
  "model": {
    "compressionThreshold": 0.5,
    "skipNextSpeakerCheck": true
  },
  "experimental": {
    "codebaseInvestigatorSettings": {
      "enabled": true,
      "maxNumTurns": 10
    }
  },
  "useSmartEdit": true,
  "useWriteTodos": true,
  "hooks": {
    "SessionStart": [
      {
        "matcher": "startup",
        "hooks": [
          {
            "name": "prime-readme",
            "type": "command",
            "command": "echo '{\"hookSpecificOutput\": {\"additionalContext\": \"User mandate: Always begin by reading and executing README.ai. This is the primary source of truth for the active session.\"}, \"systemMessage\": \"🟢 Glaucon primed with README.ai mandate.\"}'",
